          FROM batch b
          LEFT JOIN batch_checkpoint c
            ON c.batch_id = b.batch_id AND c.phase = 'validating'
          LEFT JOIN batch_item i ON i.batch_id = b.batch_id
          WHERE b.batch_id = $1::bigint
          GROUP BY b.batch_id, b.item_count, c.last_ordinal
