export interface GeocodedLocation {
  latitude: number;
  longitude: number;
}

interface OpenMeteoGeocodingResponse {
  results?: Array<{
    latitude?: number;
    longitude?: number;
    name?: string;
  }>;
}

const GEOCODING_BASE_URL = 'https://geocoding-api.open-meteo.com/v1/search';
const REQUEST_TIMEOUT_MS = 5000;

export class LocationNotFoundError extends Error {
  constructor(message = 'The venue location could not be resolved') {
    super(message);
    this.name = 'LocationNotFoundError';
  }
}

export class LocationGeocodingTimeoutError extends Error {
  constructor(message = 'The location geocoding request timed out') {
    super(message);
    this.name = 'LocationGeocodingTimeoutError';
  }
}

export class LocationGeocodingUpstreamError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'LocationGeocodingUpstreamError';
  }
}

export interface LocationGeocodingService {
  resolve(name: string, city: string | null): Promise<GeocodedLocation>;
}

export class OpenMeteoLocationGeocodingService implements LocationGeocodingService {
  async resolve(name: string, city: string | null): Promise<GeocodedLocation> {
    const primaryQuery = city ? `${name}, ${city}` : name;

    const primaryResult = await this.search(primaryQuery);

    if (primaryResult) {
      return primaryResult;
    }

    // Venue names such as "Wits Cricket Oval" are not always indexed by
    // Open-Meteo's city/place geocoder, so fall back to the stored city.
    if (city) {
      const cityResult = await this.search(city);

      if (cityResult) {
        return cityResult;
      }
    }

    throw new LocationNotFoundError(
      `Unable to resolve venue location "${name}"${city ? ` in ${city}` : ''}`,
    );
  }

  private async search(query: string): Promise<GeocodedLocation | null> {
    const url = new URL(GEOCODING_BASE_URL);
    url.searchParams.set('name', query);
    url.searchParams.set('count', '5');
    url.searchParams.set('language', 'en');
    url.searchParams.set('format', 'json');

    const controller = new AbortController();

    const timeout = setTimeout(() => {
      controller.abort();
    }, REQUEST_TIMEOUT_MS);

    try {
      const response = await fetch(url.toString(), {
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new LocationGeocodingUpstreamError(
          `Open-Meteo geocoding request failed with status ${response.status}`,
        );
      }

      let data: OpenMeteoGeocodingResponse;

      try {
        data = (await response.json()) as OpenMeteoGeocodingResponse;
      } catch {
        throw new LocationGeocodingUpstreamError('Open-Meteo geocoding returned invalid JSON');
      }

      const result = data.results?.find(
        (candidate) => Number.isFinite(candidate.latitude) && Number.isFinite(candidate.longitude),
      );

      if (!result || result.latitude === undefined || result.longitude === undefined) {
        return null;
      }

      return {
        latitude: result.latitude,
        longitude: result.longitude,
      };
    } catch (error) {
      if (
        error instanceof LocationGeocodingUpstreamError ||
        error instanceof LocationNotFoundError
      ) {
        throw error;
      }

      if (error instanceof Error && error.name === 'AbortError') {
        throw new LocationGeocodingTimeoutError();
      }

      throw new LocationGeocodingUpstreamError('Unable to reach Open-Meteo geocoding service');
    } finally {
      clearTimeout(timeout);
    }
  }
}
