import { describe, expect, test, vi } from 'vitest';

import {
  createFixtureWeatherService,
  type FixtureWeatherContext,
} from '../../src/modules/weather/fixture-weather.service';
import type { WeatherService } from '../../src/modules/weather/weather.service';

const venueContext: FixtureWeatherContext = {
  fixtureId: '17',
  date: '2026-08-19',
  venue: {
    venueId: '5',
    name: 'Wits Cricket Oval',
    city: 'Johannesburg',
    latitude: -26.1929,
    longitude: 28.0305,
  },
};

function weatherService(): WeatherService {
  return {
    getWeather: vi.fn(),
  } as unknown as WeatherService;
}

describe('fixture weather service', () => {
  test('uses the fixture start date and stored venue coordinates with WeatherService', async () => {
    const weather = weatherService();
    const getWeather = vi.mocked(weather.getWeather).mockResolvedValue({
      date: '2026-08-19',
      latitude: -26.1929,
      longitude: 28.0305,
      temperatureMax: 24,
      temperatureMin: 11,
      precipitationSum: 0,
      windSpeedMax: 17,
    });
    const findContext = vi.fn().mockResolvedValue(venueContext);

    const result = await createFixtureWeatherService(weather, findContext).getFixtureWeather('17');

    expect(findContext).toHaveBeenCalledWith('17');
    expect(getWeather).toHaveBeenCalledWith(-26.1929, 28.0305, '2026-08-19');
    expect(result).toMatchObject({
      fixtureId: '17',
      date: '2026-08-19',
      availability: 'available',
      venue: { name: 'Wits Cricket Oval', city: 'Johannesburg' },
      weather: { temperatureMax: 24, precipitationSum: 0 },
    });
  });

  test('does not query Open-Meteo when the fixture has no venue', async () => {
    const weather = weatherService();
    const result = await createFixtureWeatherService(
      weather,
      vi.fn().mockResolvedValue({
        fixtureId: '17',
        date: '2026-08-19',
        venue: null,
      }),
    ).getFixtureWeather('17');

    expect(result).toMatchObject({ availability: 'unavailable', reason: 'MISSING_VENUE' });
    expect(weather.getWeather).not.toHaveBeenCalled();
  });

  test('resolves a missing venue location by city, persists it, and fetches weather', async () => {
    const weather = weatherService();
    vi.mocked(weather.getWeather).mockResolvedValue({
      date: '2026-08-19', latitude: -43.5321, longitude: 172.6362,
      temperatureMax: 20, temperatureMin: 8, precipitationSum: 0, windSpeedMax: 16,
    });
    const geocoder = { resolve: vi.fn().mockResolvedValue({ latitude: -43.5321, longitude: 172.6362 }) };
    const persist = vi.fn().mockResolvedValue(undefined);
    const result = await createFixtureWeatherService(
      weather,
      vi.fn().mockResolvedValue({
        ...venueContext,
        venue: { ...venueContext.venue!, name: 'AMI Stadium', city: 'Christchurch', latitude: null, longitude: null },
      }),
      geocoder,
      persist,
    ).getFixtureWeather('17');

    expect(geocoder.resolve).toHaveBeenCalledWith('Christchurch');
    expect(geocoder.resolve).toHaveBeenCalledTimes(1);
    expect(persist).toHaveBeenCalledWith('5', -43.5321, 172.6362);
    expect(weather.getWeather).toHaveBeenCalledWith(-43.5321, 172.6362, '2026-08-19');
    expect(result).toMatchObject({ availability: 'available' });
  });

  test('falls back from an unresolved city to the raw venue name without combining queries', async () => {
    const weather = weatherService();
    vi.mocked(weather.getWeather).mockResolvedValue({
      date: '2026-08-19', latitude: -1.9501, longitude: 30.0588,
      temperatureMax: 24, temperatureMin: 15, precipitationSum: 2, windSpeedMax: 10,
    });
    const geocoder = {
      resolve: vi
        .fn()
        .mockResolvedValueOnce(null)
        .mockResolvedValueOnce({ latitude: -1.9501, longitude: 30.0588 }),
    };
    const persist = vi.fn().mockResolvedValue(undefined);
    const result = await createFixtureWeatherService(
      weather,
      vi.fn().mockResolvedValue({
        ...venueContext,
        venue: {
          ...venueContext.venue!,
          name: 'Gahanga International Cricket Stadium, Rwanda',
          city: 'Kigali City',
          latitude: null,
          longitude: null,
        },
      }),
      geocoder,
      persist,
    ).getFixtureWeather('17');

    expect(geocoder.resolve).toHaveBeenNthCalledWith(1, 'Kigali City');
    expect(geocoder.resolve).toHaveBeenNthCalledWith(2, 'Gahanga International Cricket Stadium, Rwanda');
    expect(persist).toHaveBeenCalledWith('5', -1.9501, 30.0588);
    expect(result).toMatchObject({ availability: 'available' });
  });

  test('returns LOCATION_NOT_FOUND when neither the city nor venue can be resolved', async () => {
    const weather = weatherService();
    const geocoder = { resolve: vi.fn().mockResolvedValue(null) };
    const result = await createFixtureWeatherService(
      weather,
      vi.fn().mockResolvedValue({
        ...venueContext,
        venue: { ...venueContext.venue!, latitude: null, longitude: null },
      }),
      geocoder,
      vi.fn(),
    ).getFixtureWeather('17');

    expect(result).toMatchObject({ availability: 'unavailable', reason: 'LOCATION_NOT_FOUND' });
    expect(geocoder.resolve).toHaveBeenNthCalledWith(1, 'Johannesburg');
    expect(geocoder.resolve).toHaveBeenNthCalledWith(2, 'Wits Cricket Oval');
    expect(weather.getWeather).not.toHaveBeenCalled();
  });

  test('does not query Open-Meteo when the fixture date is outside all supported ranges', async () => {
    const weather = weatherService();
    const result = await createFixtureWeatherService(
      weather,
      vi.fn().mockResolvedValue({
        ...venueContext,
        date: '1900-01-01',
      }),
    ).getFixtureWeather('17');

    expect(result).toMatchObject({ availability: 'unavailable', reason: 'UNSUPPORTED_DATE' });
    expect(weather.getWeather).not.toHaveBeenCalled();
  });

  test('returns null without querying data for an invalid or unknown fixture', async () => {
    const weather = weatherService();
    const findContext = vi.fn().mockResolvedValue(null);
    const service = createFixtureWeatherService(weather, findContext);

    await expect(service.getFixtureWeather('not-an-id')).resolves.toBeNull();
    await expect(service.getFixtureWeather('999')).resolves.toBeNull();
    expect(findContext).toHaveBeenCalledTimes(1);
    expect(weather.getWeather).not.toHaveBeenCalled();
  });
});

import { findFixtureWeatherContext, updateVenueCoordinates } from '../fixtures/fixture.repository';
import {
  type LocationGeocodingService,
  OpenMeteoLocationGeocodingService,
} from './location-geocoding.service';
import { classifyWeatherDate, type WeatherData, type WeatherService } from './weather.service';

type FixtureWeatherUnavailableReason =
  | 'MISSING_VENUE'
  | 'MISSING_COORDINATES'
  | 'UNSUPPORTED_LOCATION'
  | 'LOCATION_NOT_FOUND'
  | 'UNSUPPORTED_DATE';

export interface FixtureWeatherContext {
  fixtureId: string;
  date: string;
  venue: {
    venueId: string;
    name: string;
    city: string | null;
    latitude: number | null;
    longitude: number | null;
  } | null;
}

interface FixtureWeatherAvailable {
  fixtureId: string;
  date: string;
  availability: 'available';
  venue: { name: string; city: string | null };
  weather: WeatherData;
}

interface FixtureWeatherUnavailable {
  fixtureId: string;
  date: string;
  availability: 'unavailable';
  reason: FixtureWeatherUnavailableReason;
  venue: { name: string; city: string | null } | null;
  weather: null;
}

type FixtureWeatherResult = FixtureWeatherAvailable | FixtureWeatherUnavailable;

type FindFixtureWeatherContext = (fixtureId: string) => Promise<FixtureWeatherContext | null>;
type PersistVenueCoordinates = (venueId: string, latitude: number, longitude: number) => Promise<void>;

const databaseIdPattern = /^\d+$/;

function hasUsableCoordinates(
  venue: NonNullable<FixtureWeatherContext['venue']>,
): venue is NonNullable<FixtureWeatherContext['venue']> & {
  latitude: number;
  longitude: number;
} {
  if (venue.latitude === null || venue.longitude === null) {
    return false;
  }

  return (
    Number.isFinite(venue.latitude) &&
    Number.isFinite(venue.longitude) &&
    venue.latitude >= -90 &&
    venue.latitude <= 90 &&
    venue.longitude >= -180 &&
    venue.longitude <= 180
  );
}
export interface FixtureWeatherService {
  getFixtureWeather(fixtureId: string): Promise<FixtureWeatherResult | null>;
}

export function createFixtureWeatherService(
  weatherService: WeatherService,
  findContext: FindFixtureWeatherContext = findFixtureWeatherContext,
  geocodingService: LocationGeocodingService = new OpenMeteoLocationGeocodingService(),
  persistVenueCoordinates: PersistVenueCoordinates = updateVenueCoordinates,
): FixtureWeatherService {
  return {
    async getFixtureWeather(fixtureId) {
      if (!databaseIdPattern.test(fixtureId)) {
        return null;
      }

      const context = await findContext(fixtureId);
      if (!context) {
        return null;
      }

      if (!context.venue) {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'MISSING_VENUE',
          venue: null,
          weather: null,
        };
      }

      const venue = { name: context.venue.name, city: context.venue.city };
      let latitude = context.venue.latitude;
      let longitude = context.venue.longitude;
      if (latitude === null || longitude === null) {
        const queries = context.venue.city
          ? [context.venue.city, context.venue.name]
          : [context.venue.name];
        let resolved = null;
        for (const query of queries) {
          resolved = await geocodingService.resolve(query);
          if (resolved) break;
        }
        if (!resolved) {
          return {
            fixtureId: context.fixtureId,
            date: context.date,
            availability: 'unavailable',
            reason: 'LOCATION_NOT_FOUND',
            venue,
            weather: null,
          };
        }
        latitude = resolved.latitude;
        longitude = resolved.longitude;
        await persistVenueCoordinates(context.venue.venueId, latitude, longitude);
      }

      const resolvedVenue = { ...context.venue, latitude, longitude };
      if (!hasUsableCoordinates(resolvedVenue)) {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'UNSUPPORTED_LOCATION',
          venue,
          weather: null,
        };
      }

      if (classifyWeatherDate(context.date) === 'unsupported') {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'UNSUPPORTED_DATE',
          venue,
          weather: null,
        };
      }

      const weather = await weatherService.getWeather(
        latitude,
        longitude,
        context.date,
      );

      return {
        fixtureId: context.fixtureId,
        date: context.date,
        availability: 'available',
        venue,
        weather,
      };
    },
  };
}

