export interface GeocodedLocation {
  latitude: number;
  longitude: number;
}

interface OpenMeteoGeocodingResponse {
  results?: Array<{ latitude?: number; longitude?: number }>;
}

const GEOCODING_BASE_URL = 'https://geocoding-api.open-meteo.com/v1/search';
const REQUEST_TIMEOUT_MS = 5000;

export class LocationGeocodingTimeoutError extends Error {
  constructor(message = 'The location geocoding request timed out') {
    super(message);
    this.name = 'LocationGeocodingTimeoutError';
  }
}

export class LocationGeocodingUpstreamError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'LocationGeocodingUpstreamError';
  }
}

export interface LocationGeocodingService {
  resolve(query: string): Promise<GeocodedLocation | null>;
}

export class OpenMeteoLocationGeocodingService implements LocationGeocodingService {
  async resolve(query: string): Promise<GeocodedLocation | null> {
    const url = new URL(GEOCODING_BASE_URL);
    url.searchParams.set('name', query);
    url.searchParams.set('count', '1');
    url.searchParams.set('language', 'en');
    url.searchParams.set('format', 'json');
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

    try {
      const response = await fetch(url.toString(), { signal: controller.signal });
      if (!response.ok) {
        throw new LocationGeocodingUpstreamError(
          `Open-Meteo geocoding request failed with status ${response.status}`,
        );
      }
      let data: OpenMeteoGeocodingResponse;
      try {
        data = (await response.json()) as OpenMeteoGeocodingResponse;
      } catch {
        throw new LocationGeocodingUpstreamError('Open-Meteo geocoding returned invalid JSON');
      }
      const result = data.results?.find(
        (candidate) =>
          Number.isFinite(candidate.latitude) &&
          Number.isFinite(candidate.longitude) &&
          candidate.latitude! >= -90 &&
          candidate.latitude! <= 90 &&
          candidate.longitude! >= -180 &&
          candidate.longitude! <= 180,
      );
      return result?.latitude === undefined || result.longitude === undefined
        ? null
        : { latitude: result.latitude, longitude: result.longitude };
    } catch (error) {
      if (error instanceof LocationGeocodingUpstreamError) throw error;
      if (error instanceof Error && error.name === 'AbortError') {
        throw new LocationGeocodingTimeoutError();
      }
      throw new LocationGeocodingUpstreamError('Unable to reach Open-Meteo geocoding service');
    } finally {
      clearTimeout(timeout);
    }
  }
}

import { findFixtureWeatherContext, updateVenueCoordinates } from '../fixtures/fixture.repository';
import {
  type GeocodedLocation,
  type LocationGeocodingService,
  OpenMeteoLocationGeocodingService,
} from './location-geocoding.service';
import { classifyWeatherDate, type WeatherData, type WeatherService } from './weather.service';

type FixtureWeatherUnavailableReason =
  | 'MISSING_VENUE'
  | 'MISSING_COORDINATES'
  | 'UNSUPPORTED_LOCATION'
  | 'LOCATION_NOT_FOUND'
  | 'UNSUPPORTED_DATE';

export interface FixtureWeatherContext {
  fixtureId: string;
  date: string;
  venue: {
    venueId: string;
    name: string;
    city: string | null;
    latitude: number | null;
    longitude: number | null;
  } | null;
}

interface FixtureWeatherAvailable {
  fixtureId: string;
  date: string;
  availability: 'available';
  venue: { name: string; city: string | null };
  weather: WeatherData;
}

interface FixtureWeatherUnavailable {
  fixtureId: string;
  date: string;
  availability: 'unavailable';
  reason: FixtureWeatherUnavailableReason;
  venue: { name: string; city: string | null } | null;
  weather: null;
}

type FixtureWeatherResult = FixtureWeatherAvailable | FixtureWeatherUnavailable;

type FindFixtureWeatherContext = (fixtureId: string) => Promise<FixtureWeatherContext | null>;
type PersistVenueCoordinates = (venueId: string, latitude: number, longitude: number) => Promise<void>;

const databaseIdPattern = /^\d+$/;

function hasUsableCoordinates(
  venue: NonNullable<FixtureWeatherContext['venue']>,
): venue is NonNullable<FixtureWeatherContext['venue']> & {
  latitude: number;
  longitude: number;
} {
  if (venue.latitude === null || venue.longitude === null) {
    return false;
  }

  return (
    Number.isFinite(venue.latitude) &&
    Number.isFinite(venue.longitude) &&
    venue.latitude >= -90 &&
    venue.latitude <= 90 &&
    venue.longitude >= -180 &&
    venue.longitude <= 180
  );
}
export interface FixtureWeatherService {
  getFixtureWeather(fixtureId: string): Promise<FixtureWeatherResult | null>;
}

export function createFixtureWeatherService(
  weatherService: WeatherService,
  findContext: FindFixtureWeatherContext = findFixtureWeatherContext,
  geocodingService: LocationGeocodingService = new OpenMeteoLocationGeocodingService(),
  persistVenueCoordinates: PersistVenueCoordinates = updateVenueCoordinates,
): FixtureWeatherService {
  return {
    async getFixtureWeather(fixtureId) {
      if (!databaseIdPattern.test(fixtureId)) {
        return null;
      }

      const context = await findContext(fixtureId);
      if (!context) {
        return null;
      }

      if (!context.venue) {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'MISSING_VENUE',
          venue: null,
          weather: null,
        };
      }

      const venue = { name: context.venue.name, city: context.venue.city };
      let latitude = context.venue.latitude;
      let longitude = context.venue.longitude;
      if (latitude === null || longitude === null) {
        const queries = context.venue.city
          ? [context.venue.city, context.venue.name]
          : [context.venue.name];
        let resolved: GeocodedLocation | null = null;
        for (const query of queries) {
          resolved = await geocodingService.resolve(query);
          if (resolved) break;
        }
        if (!resolved) {
          return {
            fixtureId: context.fixtureId,
            date: context.date,
            availability: 'unavailable',
            reason: 'LOCATION_NOT_FOUND',
            venue,
            weather: null,
          };
        }
        latitude = resolved.latitude;
        longitude = resolved.longitude;
        await persistVenueCoordinates(context.venue.venueId, latitude, longitude);
      }

      const resolvedVenue = { ...context.venue, latitude, longitude };
      if (!hasUsableCoordinates(resolvedVenue)) {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'UNSUPPORTED_LOCATION',
          venue,
          weather: null,
        };
      }

      if (classifyWeatherDate(context.date) === 'unsupported') {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'UNSUPPORTED_DATE',
          venue,
          weather: null,
        };
      }

      const weather = await weatherService.getWeather(
        resolvedVenue.latitude,
        resolvedVenue.longitude,
        context.date,
      );

      return {
        fixtureId: context.fixtureId,
        date: context.date,
        availability: 'available',
        venue,
        weather,
      };
    },
  };
}

import { afterEach, describe, expect, test, vi } from 'vitest';

import {
  LocationGeocodingTimeoutError,
  LocationGeocodingUpstreamError,
  OpenMeteoLocationGeocodingService,
} from '../../src/modules/weather/location-geocoding.service';

describe('OpenMeteoLocationGeocodingService', () => {
  afterEach(() => {
    vi.restoreAllMocks();
    vi.useRealTimers();
  });

  test('uses the supplied city query without constructing a venue-city compound', async () => {
    const fetchMock = vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      new Response(JSON.stringify({ results: [{ latitude: -43.5321, longitude: 172.6362 }] })),
    );

    await expect(new OpenMeteoLocationGeocodingService().resolve('Christchurch')).resolves.toEqual({
      latitude: -43.5321,
      longitude: 172.6362,
    });
    expect(new URL(String(fetchMock.mock.calls[0]?.[0])).searchParams.get('name')).toBe('Christchurch');
  });

  test('returns null when the provider cannot resolve a location', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(new Response(JSON.stringify({ results: [] })));
    await expect(new OpenMeteoLocationGeocodingService().resolve('Unknown')).resolves.toBeNull();
  });

  test.each([
    [new Response('invalid json'), LocationGeocodingUpstreamError],
    [new Response('{}', { status: 500 }), LocationGeocodingUpstreamError],
  ])('maps invalid provider responses safely', async (response, error) => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(response);
    await expect(new OpenMeteoLocationGeocodingService().resolve('Christchurch')).rejects.toBeInstanceOf(error);
  });

  test('maps a timed-out request safely', async () => {
    vi.useFakeTimers();
    vi.spyOn(globalThis, 'fetch').mockImplementation(
      (_input, init) => new Promise((_resolve, reject) => {
        init?.signal?.addEventListener('abort', () => reject(Object.assign(new Error(), { name: 'AbortError' })));
      }),
    );
    const request = new OpenMeteoLocationGeocodingService().resolve('Christchurch');
    await vi.advanceTimersByTimeAsync(5000);
    await expect(request).rejects.toBeInstanceOf(LocationGeocodingTimeoutError);
  });
});

