  longitude: number;
} {
  if (venue.latitude === null || venue.longitude === null) {
    return false;
  }

  return (
    Number.isFinite(venue.latitude) &&
    Number.isFinite(venue.longitude) &&
    venue.latitude >= -90 &&
    venue.latitude <= 90 &&
    venue.longitude >= -180 &&
    venue.longitude <= 180
  );
}
export interface FixtureWeatherService {
  getFixtureWeather(fixtureId: string): Promise<FixtureWeatherResult | null>;
}

export function createFixtureWeatherService(
  weatherService: WeatherService,
  findContext: FindFixtureWeatherContext = findFixtureWeatherContext,
  geocodingService: LocationGeocodingService = new OpenMeteoLocationGeocodingService(),
  persistVenueCoordinates: PersistVenueCoordinates = updateVenueCoordinates,
): FixtureWeatherService {
  return {
    async getFixtureWeather(fixtureId) {
      if (!databaseIdPattern.test(fixtureId)) {
        return null;
      }

      const context = await findContext(fixtureId);
      if (!context) {
        return null;
      }

      if (!context.venue) {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'MISSING_VENUE',
          venue: null,
          weather: null,
        };
      }

      const venue = { name: context.venue.name, city: context.venue.city };
      if (classifyWeatherDate(context.date) === 'unsupported') {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'UNSUPPORTED_DATE',
          venue,
          weather: null,
        };
      }

      let latitude = context.venue.latitude;
      let longitude = context.venue.longitude;
      if (latitude === null || longitude === null) {
        const queries = context.venue.city
          ? [context.venue.city, context.venue.name]
          : [context.venue.name];
        let resolved: GeocodedLocation | null = null;
        for (const query of queries) {
          resolved = await geocodingService.resolve(query);
          if (resolved) break;
        }
        if (!resolved) {
          return {
            fixtureId: context.fixtureId,
            date: context.date,
            availability: 'unavailable',
            reason: 'LOCATION_NOT_FOUND',
            venue,
            weather: null,
          };
        }
        latitude = resolved.latitude;
        longitude = resolved.longitude;
        await persistVenueCoordinates(context.venue.venueId, latitude, longitude);
      }

      const resolvedVenue = { ...context.venue, latitude, longitude };
      if (!hasUsableCoordinates(resolvedVenue)) {
        return {
          fixtureId: context.fixtureId,
          date: context.date,
          availability: 'unavailable',
          reason: 'UNSUPPORTED_LOCATION',
          venue,
          weather: null,
        };
      }

      const weather = await weatherService.getWeather(
        resolvedVenue.latitude,
        resolvedVenue.longitude,
        context.date,
      );

      return {
        fixtureId: context.fixtureId,
        date: context.date,
        availability: 'available',
        venue,
        weather,
      };
    },
  };
}
import type { Request, RequestHandler } from 'express';

import {
  LocationGeocodingTimeoutError,
  LocationGeocodingUpstreamError,
} from './location-geocoding.service';
import {
  WeatherTimeoutError,
  WeatherUpstreamError,
  WeatherValidationError,
} from './weather.service';
import type { FixtureWeatherService } from './fixture-weather.service';

function pathParameter(request: Request, name: string): string {
  const value = request.params[name];
  if (value === undefined) {
    throw new Error(`Expected route parameter "${name}" was not provided.`);
  }
  return value;
}

export function getFixtureWeather(service: FixtureWeatherService): RequestHandler {
  return (request, response) => {
    void (async () => {
      try {
        const result = await service.getFixtureWeather(pathParameter(request, 'fixtureId'));
        if (!result) {
          response.status(404).json({
            error: { code: 'NOT_FOUND', message: 'Fixture not found.' },
          });
          return;
        }

        response.status(200).json({ data: result });
      } catch (error) {
        request.log?.error({ err: error }, 'Fixture weather API request failed');

        if (error instanceof WeatherValidationError) {
          response.status(503).json({
            error: {
              code: 'WEATHER_SERVICE_UNAVAILABLE',
              message: 'Weather information is temporarily unavailable.',
            },
          });
          return;
        }

        if (error instanceof WeatherTimeoutError) {
          response.status(504).json({
            error: {
              code: 'UPSTREAM_TIMEOUT',
              message: 'The weather provider did not respond in time.',
            },
          });
          return;
        }

        if (error instanceof WeatherUpstreamError) {
          response.status(502).json({
            error: { code: 'UPSTREAM_ERROR', message: 'The weather provider returned an error.' },
          });
          return;
        }

        if (error instanceof LocationGeocodingTimeoutError) {
          response.status(504).json({
            error: {
              code: 'UPSTREAM_TIMEOUT',
              message: 'The location provider did not respond in time.',
            },
          });
          return;
        }

        if (error instanceof LocationGeocodingUpstreamError) {
          response.status(502).json({
            error: { code: 'UPSTREAM_ERROR', message: 'The location provider returned an error.' },
          });
          return;
        }

        response.status(503).json({
          error: {
            code: 'WEATHER_SERVICE_UNAVAILABLE',
            message: 'Weather information is temporarily unavailable.',
          },
        });
      }
    })();
  };
}

